    #[test]
    fn health_advice_pool_each_cell_has_at_least_three_variants() {
        // Phase 2: 셀당 변형 풀 ≥ 3 (변형 A 기존 + B/C 신규). 셀 풀이 1개로 줄면
        // 같은 셀이 한 달에 4-5회 반복될 때 변형 회전이 안 돼 사용자 체감 다양성 저하.
        for elem in all_elements() {
            for rel in all_relations() {
                let pool = health_advice_pool(rel, elem);
                assert!(
                    pool.len() >= 3,
                    "pool ({:?}, {:?}) has only {} variant(s) — Phase 2 expects >= 3",
                    elem,
                    rel,
                    pool.len(),
                );
            }
        }
    }

    #[test]
    fn health_advice_pair_rotates_within_pool_with_seed() {
        // 같은 셀이라도 seed가 바뀌면 풀 인덱스가 회전해 모든 변형이 차례로 등장.
        // 풀 사이즈 N → seed 0..N 호출 시 N개 unique variant 등장.
        use std::collections::HashSet;
        for elem in all_elements() {
            for rel in all_relations() {
                let pool = health_advice_pool(rel, elem);
                let mut seen = HashSet::new();
                for seed in 0..pool.len() as u64 {
                    let (s, _) = health_advice_pair(rel, elem, seed);
                    seen.insert(s);
                }
                assert_eq!(
                    seen.len(),
                    pool.len(),
                    "seed rotation incomplete for ({:?}, {:?}): expected {}, got {}",
                    elem,
                    rel,
                    pool.len(),
                    seen.len(),
                );
            }
        }
    }

